-- создаём расширение pgvector
CREATE EXTENSION IF NOT EXISTS vector;

-- таблица пользователей
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255),
    email VARCHAR(255) UNIQUE,
    password VARCHAR(255),
    token VARCHAR(255),
    created_at DATE,
    updated_at DATE,
    features JSONB,
    embedding VECTOR(768)  -- размер векторов
);

-- индекс для поиска по embedding
CREATE INDEX IF NOT EXISTS users_embedding_idx ON users
    USING ivfflat (embedding vector_cosine_ops)
    WITH (lists = 100);

-- таблица растений
CREATE TABLE IF NOT EXISTS plants (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255),
    features JSONB,
    embedding VECTOR(768)
);

-- индекс для поиска по embedding
CREATE INDEX IF NOT EXISTS plants_embedding_idx ON plants
    USING ivfflat (embedding vector_cosine_ops)
    WITH (lists = 100);

-- связь пользователей и растений
CREATE TABLE IF NOT EXISTS user_plants (
    user_id INT REFERENCES users(id) ON DELETE CASCADE,
    plant_id INT REFERENCES plants(id) ON DELETE CASCADE,
    favorite BOOLEAN,
    my_plant BOOLEAN,
    score FLOAT,
    features JSONB,
    PRIMARY KEY (user_id, plant_id)
);


